// İki giriş de buradan geçer:
//  • Webhook ile gelen istekte alanlar "body" içindedir,
//  • Workflow 05'in /aliskanlik ve /yaptim komutlarında alanlar doğrudan gelir.
// Telegram ile aynı sözdizimi: {"metin": "ekle Su iç"} · {"metin": "yaptim 2 dün"}
// Yapılandırılmış alanlar da olur: {"islem": "yaptim", "id": 2, "gun": "dun"}
const j = $input.first().json || {};
const webhooktan = Object.prototype.hasOwnProperty.call(j, 'body');
const govde = webhooktan ? (j.body || {}) : j;

const chat_id = govde.chat_id ? String(govde.chat_id) : '';
const ISLEMLER = { ekle: 'ekle', sil: 'sil', geri: 'geri', yaptim: 'yaptim', 'yaptım': 'yaptim', liste: 'liste' };

let islem = String(govde.islem || '').trim().toLowerCase();
let arg = '';
const metin = String(govde.metin || '').trim();
if (metin) {
  const ilk = metin.split(/\s+/)[0].toLowerCase();
  if (ISLEMLER[ilk]) {
    islem = ISLEMLER[ilk];
    arg = metin.slice(ilk.length).trim();
  } else {
    islem = 'bilinmeyen';
    arg = metin;
  }
} else {
  islem = ISLEMLER[islem] || (islem ? 'bilinmeyen' : 'liste');
  arg = [govde.id || govde.ad || '', govde.gun || ''].join(' ').trim();
}

// "dün" yalnızca yaptim için anlamlı: argümanın sonunda aranır.
let dun = false;
if (islem === 'yaptim' && /\s*\b(dün|dun)$/i.test(arg)) {
  dun = true;
  arg = arg.replace(/\s*\b(dün|dun)$/i, '').trim();
}

return [{ json: { islem, arg, dun, chat_id, webhooktan } }];

// Ekle / yaptım / geri al / sil / liste işlemlerini uygular.
// Okuma zinciri hata verdiyse: dosya bozuk/erişilemez ise çalışma durdurulur —
// aksi hâlde liste boş sanılıp üzerine yazılır ve tüm seriler kaybolur.
const okuHata = $('Alışkanlıkları Oku').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Alışkanlıkları Çıkar').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('aliskanliklar.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}

const istek = $('İsteği Al (Alışkanlık)').first().json;
const okunan = dosyaYok ? {} : ($input.first().json || {});
const veri = okunan.data || okunan;
const ham = veri.aliskanliklar || [];
const aliskanliklar = (Array.isArray(ham) ? ham : [])
  .filter((a) => a && a.ad)
  .map((a) => ({ ...a, gunler: Array.isArray(a.gunler) ? [...a.gunler] : [] }));
const sonHatirlatma = veri.sonHatirlatma || null;

// Tarihler yerel saatle (GENERIC_TIMEZONE): "bugün" sizin gününüzdür.
const iki = (n) => String(n).padStart(2, '0');
const anahtar = (d) => d.getFullYear() + '-' + iki(d.getMonth() + 1) + '-' + iki(d.getDate());
const gunEkle = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
const bugun = new Date();
const bugunA = anahtar(bugun);
const kucuk = (s) => String(s || '').toLocaleLowerCase('tr-TR');

// Seri: bugün işaretliyse bugünden, değilse dünden geriye kesintisiz gün sayısı.
const seri = (a) => {
  const set = new Set(a.gunler);
  let d = set.has(bugunA) ? bugun : gunEkle(bugun, -1);
  let n = 0;
  while (set.has(anahtar(d))) { n++; d = gunEkle(d, -1); }
  return n;
};
const rekor = (a) => {
  const gunler = [...new Set(a.gunler)].sort();
  let en = 0, su = 0, onceki = null;
  for (const g of gunler) {
    const t = Date.UTC(+g.slice(0, 4), +g.slice(5, 7) - 1, +g.slice(8, 10));
    su = onceki !== null && t - onceki === 86400000 ? su + 1 : 1;
    en = Math.max(en, su);
    onceki = t;
  }
  return en;
};
const son7 = (a) => {
  const set = new Set(a.gunler);
  let s = '';
  for (let i = 6; i >= 0; i--) s += set.has(anahtar(gunEkle(bugun, -i))) ? '●' : '○';
  return s;
};
const satir = (a) => {
  const n = seri(a);
  return (a.gunler.includes(bugunA) ? '✅' : '⬜') + ' #' + a.id + ' ' + a.ad +
    '  ' + son7(a) + (n > 0 ? '  🔥' + n : '');
};
const liste = () => {
  if (aliskanliklar.length === 0) return 'Henüz alışkanlık yok.\nEklemek için: /aliskanlik ekle Su iç';
  const tamam = aliskanliklar.filter((a) => a.gunler.includes(bugunA)).length;
  return '🔥 Alışkanlıklar — bugün ' + tamam + '/' + aliskanliklar.length + '\n' +
    aliskanliklar.map(satir).join('\n') +
    '\n\nSon 7 gün soldan sağa: ● yapıldı ○ yapılmadı\nİşaretlemek için: /yaptim <numara>';
};
const bul = (arg) => {
  const m = String(arg).match(/^#?(\d+)$/);
  if (m) return aliskanliklar.find((a) => Number(a.id) === Number(m[1])) || null;
  const q = kucuk(arg).trim();
  if (!q) return null;
  return aliskanliklar.find((a) => kucuk(a.ad) === q) ||
         aliskanliklar.find((a) => kucuk(a.ad).includes(q)) || null;
};

let mesaj = '';
let yazilsin = false;
let hata = false;

if (istek.islem === 'liste') {
  mesaj = liste();
} else if (istek.islem === 'ekle') {
  const ad = istek.arg.replace(/\s+/g, ' ').trim().slice(0, 80);
  if (!ad) {
    hata = true;
    mesaj = 'Kullanım: /aliskanlik ekle Su iç (2 L)';
  } else if (aliskanliklar.some((a) => kucuk(a.ad) === kucuk(ad))) {
    hata = true;
    mesaj = '"' + ad + '" zaten listede.';
  } else {
    const id = aliskanliklar.reduce((mx, a) => Math.max(mx, Number(a.id) || 0), 0) + 1;
    aliskanliklar.push({ id, ad, olusturulma: new Date().toISOString(), gunler: [] });
    yazilsin = true;
    mesaj = '➕ Eklendi: #' + id + ' ' + ad + '\nYaptığınız gün: /yaptim ' + id;
  }
} else if (istek.islem === 'yaptim' || istek.islem === 'geri' || istek.islem === 'sil') {
  const a = bul(istek.arg);
  if (!a) {
    hata = true;
    mesaj = (istek.arg ? '"' + istek.arg + '" bulunamadı.' : 'Hangi alışkanlık? Numarasını ya da adını yazın.') +
      '\n\n' + liste();
  } else if (istek.islem === 'sil') {
    aliskanliklar.splice(aliskanliklar.indexOf(a), 1);
    yazilsin = true;
    mesaj = '🗑 Silindi: #' + a.id + ' ' + a.ad;
  } else {
    const gun = istek.dun ? anahtar(gunEkle(bugun, -1)) : bugunA;
    const ne = istek.dun ? 'dün' : 'bugün';
    if (istek.islem === 'geri') {
      if (!a.gunler.includes(gun)) {
        mesaj = a.ad + ' ' + ne + ' zaten işaretli değil.';
      } else {
        a.gunler = a.gunler.filter((g) => g !== gun);
        yazilsin = true;
        mesaj = '↩️ Geri alındı: ' + a.ad + ' (' + ne + ')';
      }
    } else if (a.gunler.includes(gun)) {
      mesaj = '✅ ' + a.ad + ' ' + ne + ' zaten işaretli. 🔥 Seri: ' + seri(a) + ' gün';
    } else {
      // En fazla 400 gün tutulur; dosya yıllarca şişmesin.
      a.gunler = [...a.gunler, gun].sort().slice(-400);
      yazilsin = true;
      const n = seri(a);
      const r = rekor(a);
      mesaj = '✅ ' + a.ad + ' — ' + ne + ' işaretlendi. 🔥 Seri: ' + n + ' gün' +
        (n > 1 && n === r ? ' (rekor!)' : '');
      const kalan = aliskanliklar.filter((x) => !x.gunler.includes(bugunA));
      if (!istek.dun) {
        mesaj += kalan.length ? '\nBugün kalan: ' + kalan.map((x) => x.ad).join(', ') : '\n🎉 Bugünkü hepsi tamam!';
      }
    }
  }
} else {
  hata = true;
  mesaj = [
    'Alışkanlık komutları:',
    '• /aliskanlik → liste ve seriler',
    '• /aliskanlik ekle Su iç',
    '• /yaptim 2 · /yaptim su · /yaptim 2 dün',
    '• /aliskanlik geri 2 · /aliskanlik sil 2',
  ].join('\n');
}

const sonuc = aliskanliklar.map((a) => ({
  id: a.id, ad: a.ad, bugun: a.gunler.includes(bugunA), seri: seri(a), rekor: rekor(a), son7: son7(a),
}));

return [{
  json: {
    islem: istek.islem, chat_id: istek.chat_id, webhooktan: istek.webhooktan,
    mesaj, hata, sonuc, yazilsin, aliskanliklar, sonHatirlatma,
  },
}];

// Yanıt düğümü yalnızca webhook ile gelen isteklerde çalışmalı;
// workflow 05'ten gelen çağrıda yanıtlanacak bir HTTP isteği yoktur.
const j = $input.first().json;
return j.webhooktan ? [{ json: j }] : [];

// İstek Telegram'dan geldiyse sonuç oraya gider.
const j = $input.first().json;
if (!j.chat_id) return [];
return [{ json: { chat_id: j.chat_id, text: String(j.mesaj).slice(0, 3900) } }];

// Dosyaya yalnızca alışkanlık listesi ve son hatırlatma günü yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { aliskanliklar: j.aliskanliklar, sonHatirlatma: j.sonHatirlatma } }];

// Akşam kontrolü: bugün işaretlenmemiş alışkanlık varsa tek mesajda hatırlatır.
// Hepsi yapıldıysa ya da liste boşsa sessiz kalır. Aynı gün ikinci kez
// göndermez (sonHatirlatma) — "Elle Test Et" ile çalıştırıldığında hariç.
const okuHata = $('Alışkanlıkları Oku (Akşam)').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Alışkanlıkları Çıkar (Akşam)').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('aliskanliklar.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}
if (dosyaYok) return [{ json: { gonderilecek: false, yazilsin: false } }];

let elle = false;
try { elle = $('Elle Test Et (Alışkanlık)').all().length > 0; } catch (e) { elle = false; }

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const okunan = $input.first().json || {};
const veri = okunan.data || okunan;
const aliskanliklar = (Array.isArray(veri.aliskanliklar) ? veri.aliskanliklar : [])
  .filter((a) => a && a.ad)
  .map((a) => ({ ...a, gunler: Array.isArray(a.gunler) ? a.gunler : [] }));

const iki = (n) => String(n).padStart(2, '0');
const anahtar = (d) => d.getFullYear() + '-' + iki(d.getMonth() + 1) + '-' + iki(d.getDate());
const bugun = new Date();
const bugunA = anahtar(bugun);
const seri = (a) => {
  const set = new Set(a.gunler);
  const d = new Date(bugun);
  d.setDate(d.getDate() - 1);
  let n = 0;
  while (set.has(anahtar(d))) { n++; d.setDate(d.getDate() - 1); }
  return n;
};

const eksik = aliskanliklar.filter((a) => !a.gunler.includes(bugunA));
if (eksik.length === 0 || (!elle && veri.sonHatirlatma === bugunA)) {
  return [{ json: { gonderilecek: false, yazilsin: false } }];
}

const tamam = aliskanliklar.length - eksik.length;
const satirlar = eksik.map((a) => {
  const n = seri(a);
  return '⬜ #' + a.id + ' ' + a.ad + (n > 0 ? ' — 🔥 ' + n + ' günlük seri bozulmasın' : '');
});
const text = '🌙 Bugün henüz yapılmayanlar:\n' + satirlar.join('\n') +
  '\n\n✅ ' + tamam + '/' + aliskanliklar.length + ' tamam. İşaretlemek için: /yaptim ' + eksik[0].id;
const html = '<h3>🌙 Bugün henüz yapılmayanlar</h3><ul>' +
  satirlar.map((s) => '<li>' + esc(s.slice(2)) + '</li>').join('') + '</ul><p>✅ ' + tamam + '/' +
  aliskanliklar.length + ' tamam.</p>';

return [{
  json: {
    gonderilecek: true,
    yazilsin: true,
    text,
    konu: '🌙 Alışkanlık: ' + eksik.length + ' tanesi bugün yapılmadı',
    html,
    govde: { aliskanliklar: veri.aliskanliklar, sonHatirlatma: bugunA },
  },
}];

// Telegram kuruluysa hatırlatma oraya gider; değilse bu dal boş döner.
const j = $input.first().json;
if (!j.gonderilecek) return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE hatırlatma mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
if (!j.gonderilecek) return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];

// Hatırlatma gittiyse günü işaretle: aynı gün ikinci kez gönderilmez.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: j.govde }];
